python3 -c "
import json
d=json.load(open('evidence/runs/angular-super-productivity-v2-13-15/u18i-closure-correction-green.json'))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'.'+k)
    elif isinstance(o,list):
        print(p, '[list len %d]'%len(o))
    else:
        print(p, '=', (str(o)[:120]))
walk(d)
" | head -120

