1	/**
2	 * The u18i round of the `angular-super-productivity-v2-13-15` cell: the round
3	 * that answers the bundler.
4	 *
5	 * u18h took the source census to zero and the build reached the bundler for the
6	 * first time in this cell's history, where three families were waiting that
7	 * nothing had ever been able to see. None of them is application source in the
8	 * sense the earlier rounds meant it — one is a closure decision, one is a
9	 * stylesheet, one is a module-graph rule the type checker does not share — and
10	 * each is answered here by a reading rather than by a table.
11	 *
12	 * The @ngx-formly correction is not driven from this file: it is a fact about
13	 * the target cell, and it is corrected where the cell's ecosystem readings live.
14	 * What this driver does is the other two, and it does them with capabilities:
15	 *
16	 *  - `sass-mixin-hyphenation-successor` rewrites `@include initMaterialCssVars()`
17	 *    onto the `init-material-css-vars` the installed angular-material-css-vars
18	 *    5.0.3 declares, after resolving the stylesheet's own `@import` specifiers
19	 *    through the package's `exports` map under the `sass` condition and reading
20	 *    the mixins those files actually declare.
21	 *  - `json-module-named-import` rewrites `import {version} from '../../package.json'`
22	 *    into a default import and a destructuring, after parsing the resolved JSON
23	 *    and confirming it declares the key.
24	 *
25	 * Both are pure functions of a module and a reading. This driver is the part
26	 * that makes the readings — the closure questions — and it makes them against
27	 * the installed tree, never against a table of what the tree ought to contain.
28	 */
29	
30	import { readFile, writeFile } from 'node:fs/promises';
31	import { existsSync, readFileSync } from 'node:fs';
32	import * as path from 'pathe';
33	import {
34		renameHyphenatedSassMixins,
35		readSassMixinDeclarations,
36		rewriteJsonNamedImports,
37		rebaseStylesheetUrls,
38		type JsonModuleReading,
39		type StylesheetTreeReading,
40		type UrlRebaseChange,
41		type SassMixinDeclaration,
42		type SassMixinRenameChange,
43		type JsonNamedImportChange,
44	} from '../../../frameworks/angular/src/index.ts';
45	import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-super-productivity-apply-run.ts';
46	
47	/** The stylesheet the bundler names, and the environments that name the manifest. */
48	export const STYLE_ENTRY = 'src/styles/themes.scss';
49	export const ENVIRONMENT_MODULES: readonly string[] = Object.freeze([
50		'src/environments/environment.ts',
51		'src/environments/environment.prod.ts',
52	]);
53	
54	type ExportsMap = Readonly<Record<string, unknown>>;
55	
56	/**
57	 * The file a package's `exports` map answers `subpath` with under the stylesheet
58	 * pipeline's conditions, or null when the map does not answer it.
59	 *
60	 * Only `sass` and `style` are honoured, and `default` after them, because those
61	 * are the conditions the Angular builder's sass loader resolves with. A package
62	 * publishing no map answers nothing here and is left to the file candidates.
63	 */
64	export function sassEntryPointOf(manifest: ExportsMap, subpath: string): string | null {
65		const map = manifest['exports'];
66		if (typeof map !== 'object' || map === null) return null;
67		const entry = (map as Record<string, unknown>)[subpath];
68		if (typeof entry === 'string') return entry;
69		if (typeof entry !== 'object' || entry === null) return null;
70		for (const condition of ['sass', 'style', 'default']) {
71			const answered = (entry as Record<string, unknown>)[condition];
72			if (typeof answered === 'string') return answered;
73		}
74		return null;
75	}
76	
77	/**
78	 * Resolve a bare stylesheet specifier to a file inside the installed closure.
79	 *
80	 * The package's own `exports` map is consulted first — a package that publishes
81	 * one is reachable through it and only through it — and sass's file candidates
82	 * are the fallback for a package that publishes none.
83	 */
84	export function resolveSassSpecifier(specifier: string, modulesRoot: string): string | null {
85		const segments = specifier.split('/');
86		const packageName = specifier.startsWith('@') ? segments.slice(0, 2).join('/') : segments[0] ?? '';
87		const subpath = specifier.slice(packageName.length);
88		const manifestPath = path.join(modulesRoot, packageName, 'package.json');
89		if (existsSync(manifestPath)) {
90			const manifest: unknown = JSON.parse(readFileSync(manifestPath, 'utf8'));
91			if (typeof manifest === 'object' && manifest !== null) {
92				const answered = sassEntryPointOf(manifest as ExportsMap, subpath === '' ? '.' : `.${subpath}`);
93				if (answered !== null) return path.join(modulesRoot, packageName, answered);
94			}
95		}
96		const direct = path.join(modulesRoot, specifier);
97		for (const candidate of [
98			direct,
99			`${direct}.scss`,
100			path.join(path.dirname(direct), `_${path.basename(direct)}.scss`),
101			path.join(direct, '_index.scss'),
102			path.join(direct, 'index.scss'),
103		])
104			if (existsSync(candidate)) return candidate;
105		return null;
106	}
107	
108	/**
109	 * Every mixin the stylesheet's own `@import` rules put in its global namespace.
110	 *
111	 * `@import` hoists a file's members into the importing file, and `@forward`
112	 * re-exports the members of another file through the one doing the forwarding,
113	 * so both are followed. `@use` is not followed: its members are reachable only
114	 * through the namespace it binds, and a namespaced `@include a.b()` is a call
115	 * this capability passes over.
116	 */
117	export async function readImportedSassSurface(
118		stylesheet: string,
119		modulesRoot: string,
120	): Promise<Readonly<{ surface: readonly SassMixinDeclaration[]; files: readonly string[] }>> {
121		const source = await readFile(stylesheet, 'utf8');
122		const surface: SassMixinDeclaration[] = [];
123		const files: string[] = [];
124		const seen = new Set<string>();
125		const queue: string[] = [];
126		for (const match of source.matchAll(/@import\s+['"]([^'"\n]+)['"]/gu)) {
127			const specifier = match[1];
128			if (specifier === undefined || specifier.startsWith('.') || specifier.startsWith('/')) continue;
129			const resolved = resolveSassSpecifier(specifier, modulesRoot);
130			if (resolved !== null) queue.push(resolved);
131		}
132		while (queue.length > 0) {
133			const file = queue.shift();
134			if (file === undefined || seen.has(file) || !existsSync(file)) continue;
135			seen.add(file);
136			files.push(path.relative(modulesRoot, file));
137			const text = await readFile(file, 'utf8');
138			surface.push(...readSassMixinDeclarations(text));
139			for (const match of text.matchAll(/@forward\s+['"]([^'"\n]+)['"]/gu)) {
140				const specifier = match[1];
141				if (specifier === undefined) continue;
142				const base = specifier.startsWith('.')
143					? path.resolve(path.dirname(file), specifier)
144					: resolveSassSpecifier(specifier, modulesRoot);
145				if (base === null) continue;
146				for (const candidate of [
147					base,
148					`${base}.scss`,
149					path.join(path.dirname(base), `_${path.basename(base)}.scss`),
150				])
151					if (existsSync(candidate)) {
152						queue.push(candidate);
153						break;
154					}
155			}
156		}
157		return Object.freeze({ surface: Object.freeze(surface), files: Object.freeze(files.sort()) });
158	}
159	
160	export type RoundOutcome = Readonly<{
161		capability: string;
162		filesChanged: readonly string[];
163		changes: readonly string[];
164		unhandled: readonly string[];
165		reading: readonly string[];
166	}>;
167	
168	/** The Sass mixin round, read off the installed closure the stylesheet imports. */
169	export async function sassMixinRound(): Promise<RoundOutcome> {
170		const modulesRoot = path.join(APPLIED_TREE, 'node_modules');
171		const stylesheet = path.join(APPLIED_TREE, STYLE_ENTRY);
172		const { surface, files } = await readImportedSassSurface(stylesheet, modulesRoot);
173		const source = await readFile(stylesheet, 'utf8');
174		const migration = renameHyphenatedSassMixins(STYLE_ENTRY, source, surface);
175		if (migration.changed) await writeFile(stylesheet, migration.source);
176		return Object.freeze({
177			capability: 'sass-mixin-hyphenation-successor',
178			filesChanged: Object.freeze(migration.changed ? [STYLE_ENTRY] : []),
179			changes: Object.freeze(
180				migration.changes.map(
181					(change: SassMixinRenameChange) =>
182						`${STYLE_ENTRY} line ${String(change.line)}: @include ${change.from} → ${change.to} ` +
183						`(${String(change.declaration.parameters.length)} declared parameter(s), ` +
184						`${String(change.declaration.defaults)} with defaults; the call passes ` +
185						`${String(change.arguments)})`,
186				),
187			),
188			unhandled: migration.unhandled,
189			reading: Object.freeze([
190				`surface read from ${String(files.length)} file(s) the stylesheet's @import rules resolve to: ` +
191					files.join(', '),
192				`${String(surface.length)} mixin declaration(s) in that surface`,
193			]),
194		});
195	}
196	
197	/** The JSON named-import round, read off the resolved manifest itself. */
198	export async function jsonNamedImportRound(): Promise<RoundOutcome> {
199		const changed: string[] = [];
200		const changes: string[] = [];
201		const unhandled: string[] = [];
202		const reading: string[] = [];
203		for (const file of ENVIRONMENT_MODULES) {
204			const absolute = path.join(APPLIED_TREE, file);
205			if (!existsSync(absolute)) continue;
206			const source = await readFile(absolute, 'utf8');
207			const parsedFor: JsonModuleReading = (specifier: string) => {
208				const target = path.resolve(path.dirname(absolute), specifier);
209				if (!existsSync(target)) return null;
210				try {
211					const value: unknown = JSON.parse(readFileSync(target, 'utf8'));
212					if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
213					reading.push(
214						`${file}: '${specifier}' resolved to ${path.relative(APPLIED_TREE, target)}, ` +
215							`${String(Object.keys(value).length)} top-level key(s)`,
216					);
217					return value as Readonly<Record<string, unknown>>;
218				} catch {
219					return null;
220				}
221			};
222			const migration = rewriteJsonNamedImports(file, source, parsedFor);
223			unhandled.push(...migration.unhandled);
224			if (!migration.changed) continue;
225			await writeFile(absolute, migration.source);
226			changed.push(file);
227			for (const change of migration.changes as readonly JsonNamedImportChange[])
228				changes.push(
229					`${file} line ${String(change.line)}: import { ` +
230						`${change.bindings.map((binding) => binding.exported).join(', ')} } from ` +
231						`'${change.specifier}' → default import ${change.defaultLocal} plus a destructuring of ` +
232						'the same names',
233				);
234		}
235		return Object.freeze({
236			capability: 'json-module-named-import',
237			filesChanged: Object.freeze(changed),
238			changes: Object.freeze(changes),
239			unhandled: Object.freeze(unhandled),
240			reading: Object.freeze(reading),
241		});
242	}
243	
244	/**
245	 * The url-rebase round.
246	 *
247	 * The entry stylesheets are the ones `angular.json` names in the build's
248	 * `styles` option, and the partials are every `.scss` under `src/` those entries
249	 * reach by `@import`. Both readings are made from the tree: the entry list from
250	 * the workspace file, the import graph by following each entry's own relative
251	 * `@import` rules, so nothing here assumes a layout.
252	 */
253	export async function urlRebaseRound(): Promise<RoundOutcome> {
254		const workspace: unknown = JSON.parse(readFileSync(path.join(APPLIED_TREE, 'angular.json'), 'utf8'));
255		const entries = new Set<string>();
256		const projects = (workspace as { projects?: Record<string, unknown> }).projects ?? {};
257		for (const project of Object.values(projects)) {
258			const styles = (
259				project as { architect?: { build?: { options?: { styles?: unknown } } } }
260			).architect?.build?.options?.styles;
261			if (!Array.isArray(styles)) continue;
262			for (const style of styles) if (typeof style === 'string') entries.add(style);
263		}
264		// The import graph, followed from each entry through its own relative rules.
265		const importedBy = new Map<string, Set<string>>();
266		const queue = [...entries].map((entry) => Object.freeze({ file: entry, root: entry }));
267		const seen = new Set<string>();
268		while (queue.length > 0) {
269			const next = queue.shift();
270			if (next === undefined) continue;
271			const key = `${next.root}\u0000${next.file}`;
272			if (seen.has(key)) continue;
273			seen.add(key);
274			const absolute = path.join(APPLIED_TREE, next.file);
275			if (!existsSync(absolute)) continue;
276			const text = await readFile(absolute, 'utf8');
277			for (const match of text.matchAll(/@import\s+['"]([^'"\n]+)['"]/gu)) {
278				const specifier = match[1];
279				if (specifier === undefined) continue;
280				const base = path.join(path.dirname(next.file), specifier);
281				const candidate = [
282					base,
283					`${base}.scss`,
284					path.join(path.dirname(base), `_${path.basename(base)}.scss`),
285				].find((option) => existsSync(path.join(APPLIED_TREE, option)));
286				if (candidate === undefined) continue;
287				importedBy.set(candidate, (importedBy.get(candidate) ?? new Set()).add(path.dirname(next.root)));
288				queue.push(Object.freeze({ file: candidate, root: next.root }));
289			}
290		}
291		const changed: string[] = [];
292		const changes: string[] = [];
293		const unhandled: string[] = [];
294		for (const partial of [...importedBy.keys()].sort()) {
295			const absolute = path.join(APPLIED_TREE, partial);
296			const source = await readFile(absolute, 'utf8');
297			const reading: StylesheetTreeReading = Object.freeze({
298				carries: (treePath: string): boolean => existsSync(path.join(APPLIED_TREE, treePath)),
299				entryDirectories: Object.freeze([...(importedBy.get(partial) ?? new Set<string>())].sort()),
300			});
301			const migration = rebaseStylesheetUrls(partial, source, reading);
302			unhandled.push(...migration.unhandled);
303			if (!migration.changed) continue;
304			await writeFile(absolute, migration.source);
305			changed.push(partial);
306			for (const change of migration.changes as readonly UrlRebaseChange[])
307				changes.push(
308					`${partial} line ${String(change.line)}: url(${change.from}) → url(${change.to}) ` +
309						`(both spellings name ${change.resolved})`,
310				);
311		}
312		return Object.freeze({
313			capability: 'stylesheet-url-rebase',
314			filesChanged: Object.freeze(changed),
315			changes: Object.freeze(changes),
316			unhandled: Object.freeze(unhandled),
317			reading: Object.freeze([
318				`${String(entries.size)} entry stylesheet(s) named by angular.json: ${[...entries].sort().join(', ')}`,
319				`${String(importedBy.size)} imported partial(s) reached from them`,
320			]),
321		});
322	}
323	
324	export async function main(): Promise<void> {
325		const outcomes: RoundOutcome[] = [
326			await sassMixinRound(),
327			await jsonNamedImportRound(),
328			await urlRebaseRound(),
329		];
330		await writeFile(
331			path.join(STAGE_DIRECTORY, 'u18i-round.json'),
332			`${JSON.stringify({ capabilities: outcomes }, null, '\t')}\n`,
333		);
334		for (const outcome of outcomes)
335			process.stdout.write(
336				`${outcome.capability}: ${String(outcome.filesChanged.length)} files changed, ` +
337					`${String(outcome.changes.length)} changes, ${String(outcome.unhandled.length)} refused\n`,
338			);
339	}
340	
341	if (process.argv[1]?.endsWith('angular-super-productivity-u18i-run.ts'))
342		main().catch((error: unknown) => {
343			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
344			process.exitCode = 1;
345		});
