1	/**
2	 * The parsed-module vocabulary the source capabilities share.
3	 *
4	 * Every capability in this adapter that rewrites application source rides a
5	 * resolved binding rather than a name: the question is never "is there an
6	 * identifier spelled `Input` here", it is "does this identifier resolve to the
7	 * symbol `@angular/core` exported as `Input`". The helpers here are the small
8	 * set of operations that question decomposes into, kept in one place so that
9	 * two capabilities cannot disagree about what an import surface is.
10	 *
11	 * Nothing here is Angular specific and nothing here is application specific.
12	 */
13	
14	import { analyze } from 'yuku-analyzer';
15	
16	export type SemanticModule = ReturnType<typeof analyze>;
17	export type AstNode = NonNullable<ReturnType<SemanticModule['parentOf']>>;
18	export type ImportRecord = SemanticModule['imports'][number];
19	export type BindingSymbol = NonNullable<ImportRecord['local']>;
20	
21	/** A replacement of one source span. Spans handed to {@link applySourceEdits} must not overlap. */
22	export type SourceEdit = Readonly<{ start: number; end: number; text: string }>;
23	
24	/**
25	 * Parse one module, or fail naming the file.
26	 *
27	 * A module that does not parse is never skipped. A skipped file is counted as
28	 * unchanged, and the whole value of a changeset is that a file reported
29	 * unchanged really was unchanged.
30	 */
31	export function parseModule(capability: string, path: string, source: string): SemanticModule {
32		const module = analyze(source, { path, lang: path.endsWith('.ts') ? 'ts' : 'js' });
33		const errors = module.diagnostics.filter((entry) => entry.severity === 'error');
34		if (errors.length > 0)
35			throw new Error(
36				`${capability}: ${path} does not parse, so it cannot be rewritten and it cannot be ` +
37					`honestly counted as unchanged. Diagnostics: ` +
38					errors.map((entry) => entry.message).join('; '),
39			);
40		return module;
41	}
42	
43	/** The 1-based line `offset` sits on. */
44	export function lineOf(source: string, offset: number): number {
45		return source.slice(0, offset).split('\n').length;
46	}
47	
48	/** Apply non-overlapping edits to a string, rightmost first. */
49	export function applySourceEdits(text: string, edits: readonly SourceEdit[]): string {
50		let result = text;
51		for (const edit of [...edits].sort((left, right) => right.start - left.start))
52			result = `${result.slice(0, edit.start)}${edit.text}${result.slice(edit.end)}`;
53		return result;
54	}
55	
56	/**
57	 * One module's import surface for a single package specifier: the namespace
58	 * binding if it has one, the named bindings by exported name, and the
59	 * declarations they came from. A default binding is recorded only as `wide`,
60	 * because a member reached through one cannot be resolved by name.
61	 */
62	export type ModuleImports = Readonly<{
63		present: boolean;
64		namespace: BindingSymbol | null;
65		named: ReadonlyMap<string, BindingSymbol>;
66		declarations: readonly AstNode[];
67		wide: boolean;
68	}>;
69	
70	export function readModuleImports(module: SemanticModule, specifier: string): ModuleImports {
71		const named = new Map<string, BindingSymbol>();
72		const declarations: AstNode[] = [];
73		let namespace: BindingSymbol | null = null;
74		let present = false;
75		let wide = false;
76		for (const record of module.imports) {
77			if (record.specifier !== specifier) continue;
78			present = true;
79			const declaration = importDeclarationOf(module, record.node);
80			if (declaration !== null && !declarations.includes(declaration)) declarations.push(declaration);
81			const local = record.local;
82			if (local === null) continue;
83			if (record.isNamespace) {
84				namespace ??= local;
85				wide = true;
86				continue;
87			}
88			if (record.name === null || record.name === 'default') {
89				wide = true;
90				continue;
91			}
92			if (!named.has(record.name)) named.set(record.name, local);
93		}
94		return Object.freeze({
95			present,
96			namespace,
97			named,
98			declarations: Object.freeze(declarations),
99			wide,
100		});
101	}
102	
103	export function importDeclarationOf(module: SemanticModule, node: AstNode): AstNode | null {
104		let current: AstNode | null = node;
105		while (current !== null) {
106			if (current.type === 'ImportDeclaration') return current;
107			current = module.parentOf(current);
108		}
109		return null;
110	}
111	
112	export function namedSpecifiersOf(declaration: AstNode): readonly AstNode[] {
113		if (declaration.type !== 'ImportDeclaration') return [];
114		return declaration.specifiers.filter((specifier) => specifier.type === 'ImportSpecifier');
115	}
116	
117	/** Whether the module's root scope leaves `name` free for a capability to bind. */
118	export function isFreeRootName(module: SemanticModule, name: string): boolean {
119		return module.rootScope.find(name) === null;
120	}
121	
122	/**
123	 * Visit every node of a parsed subtree, once each.
124	 *
125	 * The estree shapes the analyzer produces are plain objects whose children are
126	 * nodes or arrays of nodes, so a structural walk reaches all of them without
127	 * enumerating the grammar. `parent` links are skipped so the walk terminates on
128	 * a graph the analyzer may have made cyclic, and a node is visited once even if
129	 * two fields reference it.
130	 */
131	export function forEachNode(root: unknown, visit: (node: AstNode) => void): void {
132		const seen = new Set<object>();
133		const step = (value: unknown): void => {
134			if (Array.isArray(value)) {
135				for (const entry of value as readonly unknown[]) step(entry);
136				return;
137			}
138			if (typeof value !== 'object' || value === null) return;
139			const record = value as Record<string, unknown>;
140			if (typeof record['type'] !== 'string') return;
141			if (seen.has(record)) return;
142			seen.add(record);
143			visit(record as unknown as AstNode);
144			for (const key of Object.keys(record)) {
145				if (key === 'parent' || key === 'loc' || key === 'range') continue;
146				step(record[key]);
147			}
148		};
149		step(root);
150	}
151	
152	/** The 0-based offset of a 1-based line and column, as a compiler reports them. */
153	export function offsetOfPosition(source: string, line: number, column: number): number | null {
154		const lines = source.split('\n');
155		if (line < 1 || line > lines.length) return null;
156		let offset = 0;
157		for (let index = 0; index < line - 1; index += 1) offset += (lines[index]?.length ?? 0) + 1;
158		const text = lines[line - 1] ?? '';
159		if (column < 1 || column > text.length + 1) return null;
160		return offset + column - 1;
161	}
162	
163	export type PlainProperty = Readonly<{ node: AstNode; name: string; value: AstNode }>;
164	
165	/**
166	 * The properties of an object literal, when every one of them is a plain,
167	 * statically named, non-computed data property. A literal carrying a spread, a
168	 * computed key, a method, or an accessor returns null: a capability that reads
